+        }
+
+      memset(&g_sdio, 0, sizeof(g_sdio));
+      memcpy(&g_sdio.dev, &g_sdio_template, sizeof(g_sdio.dev));
+      sdio_pinmux();
+      sdio_reset_hw(&g_sdio);
+      g_sdio.initialized = true;
+    }
+
+  return &g_sdio.dev;
+}
